#include "../src/network.hpp"
#include <cassert>
#include <iostream>
using namespace day;
Json fixture(const char* name){Json j;std::ifstream f(std::string("tests/fixtures/")+name);f>>j;return j;}
int main(){auto found=fixture("risuty-search.json");std::vector<Location> cities;for(auto& g:found["results"]){Location l;l.valid=true;l.country=g["country_code"];l.city=g["name"];l.zone=g["timezone"];l.lat=g["latitude"];l.lon=g["longitude"];l.geoname=g["id"];cities.push_back(l);}assert(cities.size()==2&&locationKey(cities[0])!=locationKey(cities[1])&&!sameForecastPlace(cities[0],cities[1]));State s;s.countries={{"CZ","Czechia",2,true,true,"Europe/Prague"}};s.countries[0].cityEnabled=false;for(const auto& l:cities)assert(addCountryCity(s,0,l));assert(s.regions.size()==2&&countryPlace(s.countries[0],cities[0])&&!countryPlace(s.countries[0],cities[1]));auto legacyJson=encode(s);for(auto& c:legacyJson["countries"]){c.erase("cityPinned");c.erase("cityLat");c.erase("cityLon");}auto legacy=decode(legacyJson);assert(legacy.countries[0].cityPinned&&countryPlace(legacy.countries[0],cities[0])&&!countryPlace(legacy.countries[0],cities[1]));removeCountryCity(legacy,0,1);assert(legacy.countries[0].cityEnabled&&legacy.regions.size()==1&&countryPlace(legacy.countries[0],cities[0]));auto restored=decode(encode(s));assert(restored.countries[0].cityPinned&&!countryPlace(restored.countries[0],cities[1]));Json weather=fixture("risuty-weather.json");for(auto& v:weather["daily"])if(v.is_array()&&v.size()>10)v.erase(v.begin()+10,v.end());Refresh job;job.state=s;for(auto& place:job.state.regions){place.weather=parseWeather(weather);place.updated=123;place.location.zone="Europe/Berlin";}job.state.caches["CZ"]={2026,"",123,parseHolidays(fixture("cz-holidays-2026.json"),cities[0],2026)};mergeRefresh(s,job);assert(s.regions.size()==2&&s.regions[0].weather.valid&&s.regions[1].weather.valid&&s.countries[0].zone=="Europe/Berlin");assert(s.caches["CZ"].items.size()==13&&!holidayItems(s,{2026,10,28}).empty());removeCountryCity(s,0,0);assert(s.regions.size()==1&&countryPlace(s.countries[0],s.regions[0].location)&&s.countries[0].cityLat==cities[1].lat);s.networkReport="Řisuty: forecast loaded\nCZ: holidays loaded · 13";assert(decode(encode(s)).networkReport==s.networkReport);std::cout<<"Recorded Risuty search/weather/holidays, independent identities, timezone merge and save migration: PASS\n";}
